pm.test("Status code 200", () => {
  pm.response.to.have.status(200);
});

pm.test("Token এসেছে", () => {
  const body = pm.response.json();
  pm.expect(body.token).to.be.a("string").and.not.empty;
  pm.environment.set("token", body.token);   // পরের request এর জন্য সেভ
});

pm.test("ভুল login এ token আসেনি", () => {
  const body = pm.response.json();
  pm.expect(body.token).to.be.undefined;
  pm.expect(body.reason).to.eql("Bad credentials");
});

pm.test("Status code 200", () => {
