});

const body = pm.response.json();

pm.test("bookingid এসেছে", () => {
  pm.expect(body.bookingid).to.be.a("number");
  pm.environment.set("bookingId", body.bookingid);
});

pm.test("ডেটা ঠিক আছে", () => {
  pm.expect(body.booking.firstname).to.eql("Rahul");
  pm.expect(body.booking.lastname).to.eql("Das");
  pm.expect(body.booking.totalprice).to.eql(500);
  pm.expect(body.booking.bookingdates.checkin).to.eql("2026-12-01");
});

